  m = max(m, strokeAA(f.y - 0.3 * sign(k - 0.5), w, fp) * step(0.45, h) * step(abs(f.x), 0.36));
  m = max(m, strokeAA((f.x - f.y) * 0.707, w, fp) * step(0.8, k) * step(length(f), 0.4));
